using System.Net.Http.Headers;using System.Text;
namespace Satusehat.IntegrationSdk;
internal sealed class FhirClient(SatusehatConfig c,HttpClient http,TokenProvider tokens){public async Task<FhirResponse> RequestOnceAsync(string method,string rt,string? id,string? payload,CancellationToken ct){var url=$"{c.FhirBaseUrl}/{rt}"+(string.IsNullOrWhiteSpace(id)?"":$"/{id}");using var req=new HttpRequestMessage(new HttpMethod(method.ToUpperInvariant()),url);req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",await tokens.GetAsync(ct));req.Headers.Accept.ParseAdd("application/fhir+json, application/json");if(payload is not null)req.Content=new StringContent(payload,Encoding.UTF8,method.Equals("PATCH",StringComparison.OrdinalIgnoreCase)?"application/json-patch+json":"application/fhir+json");using var r=await http.SendAsync(req,ct);var text=await r.Content.ReadAsStringAsync(ct);var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var h in r.Headers)headers[h.Key]=h.Value.FirstOrDefault()??"";foreach(var h in r.Content.Headers)headers[h.Key]=h.Value.FirstOrDefault()??"";return new((int)r.StatusCode,text,headers);}}
